import logging
from robot.libraries.BuiltIn import BuiltIn


def report_reference_configuration_id(ref_configuration_id=None):
    if ref_configuration_id is None:
        ref_configuration_id = BuiltIn().get_variable_value('${{{}}}'.format('REFERENCE_CONFIGURATION_ID'), None)
        if ref_configuration_id is None:
            logging.warning("You need to pass 'ref_configuration_id' or "
                            "set global variable ${REFERENCE_CONFIGURATION_ID}")
            return
    BuiltIn().run_keyword('taf.sw.reporting_portal.set_reference_configuration_id',
                          'ref_configuration_id={}'.format(ref_configuration_id))
